//! The codex app-server protocol, as agentmux speaks it.
//!
//! `codex app-server` speaks JSON-RPC on stdio, one message per line.
//! This crate is what both of agentmux's sides of that conversation share — the driver, which is
//! the client, and the test server that stands in for codex:
//!
//! - [`types`]: the payloads, generated by progeny from the JSON Schema the codex CLI itself
//!   publishes (`codex app-server generate-json-schema`);
//! - [`methods`]: one marker type per method codex lists, bound by [`Method`] and [`Request`] to
//!   its payload types and by a direction trait to who sends it, and an `Any*` enum per direction
//!   that classifies an incoming message by its method;
//! - [`envelope`]: the JSON-RPC framing around the payloads, written by hand.
//!
//! [`types`] and [`methods`] are generated by `crates/codex-app-server-codegen` and checked in;
//! that crate's tests fail when they differ from what its vendored schema generates.
//!
//! The types are not taken from codex's own `codex-app-server-protocol` crate, although its
//! licence would allow it, because that crate is part of codex's core rather than a protocol
//! leaf.
//! It resolves only with codex's `[patch.crates-io]` forks, brings several hundred packages with
//! native dependencies such as `aws-lc-sys`, `openssl-sys` and `libdbus-sys`, and builds only
//! against the pins in codex's own lockfile, which a dependent cannot inherit.
//! Generating them adds no dependency beyond `serde` and `serde_json`.

pub mod envelope;
// Generated, so what its lints would change belongs in the generator.
#[rustfmt::skip]
#[expect(
    clippy::too_many_lines,
    reason = "an `Any*` enum's `classify` and `method` match every method of codex's protocol in \
              one direction, and splitting them would hide that the match is exhaustive"
)]
pub mod methods;
// Generated by progeny from codex's own JSON Schema; what its lints would change belongs in the
// generator, and its own header lists what progeny could not represent.
#[rustfmt::skip]
#[expect(
    missing_docs,
    clippy::doc_markdown,
    clippy::enum_variant_names,
    clippy::too_many_lines,
    clippy::struct_field_names,
    clippy::box_collection,
    reason = "generated by progeny from `codex app-server generate-json-schema`; fix what these \
              flag in crates/codex-app-server-codegen"
)]
mod schema;

use std::fmt;
use std::marker::PhantomData;

use serde::Serialize;
use serde::de::DeserializeOwned;
use serde_json::Value;

pub use envelope::DecodeError;
pub use schema::types;

/// A JSON-RPC method: its name, and the type of its `params`.
///
/// Implemented only by the marker types in [`methods`], each for one method codex lists, so a
/// message cannot be built with one method and another method's payload.
pub trait Method {
    /// The JSON-RPC method.
    const METHOD: &'static str;
    /// What `params` carries: `()` for a method that carries none, and an `Option` for one whose
    /// parameters may be left out; either is sent without the member when there is nothing.
    type Params: Serialize + DeserializeOwned;

    /// Decode a message's `params`.
    ///
    /// # Errors
    ///
    /// Returns [`DecodeError`] when the payload does not match the generated type.
    fn params(params: &Value) -> Result<Self::Params, DecodeError> {
        envelope::decode(params)
    }
}

/// A method whose messages are requests, and the type of the `result` that answers one.
pub trait Request: Method {
    /// What `result` carries.
    type Response: Serialize + DeserializeOwned;

    /// Decode the `result` that answers this request.
    ///
    /// # Errors
    ///
    /// Returns [`DecodeError`] when the payload does not match the generated type.
    fn response(result: &Value) -> Result<Self::Response, DecodeError> {
        envelope::decode(result)
    }
}

/// A method whose messages are notifications, which are not answered.
pub trait Notification: Method {}

/// A request the client sends and the server answers.
pub trait ClientRequest: Request {}

/// A notification the client sends.
pub trait ClientNotification: Notification {}

/// A request the server sends and the client answers.
pub trait ServerRequest: Request {}

/// A notification the server sends.
pub trait ServerNotification: Notification {}

/// The `params` of a message of method `M`, not yet decoded.
///
/// The generated `Any*` enums in [`methods`] classify a message by its method alone and hold its
/// parameters in this, so a receiver matches every method exhaustively but decodes only the
/// payloads it acts on, and can only decode them as the type its method binds.
pub struct Payload<'a, M> {
    params: &'a Value,
    method: PhantomData<fn() -> M>,
}

impl<'a, M: Method> Payload<'a, M> {
    /// The `params` of a message of method `M`.
    ///
    /// Nothing is checked until [`Payload::decode`], which is what decides whether they are
    /// `M`'s.
    #[must_use]
    pub fn new(params: &'a Value) -> Self {
        Self {
            params,
            method: PhantomData,
        }
    }

    /// Decode the parameters into the type `M` binds.
    ///
    /// # Errors
    ///
    /// Returns [`DecodeError`] when the payload does not match the generated type.
    pub fn decode(self) -> Result<M::Params, DecodeError> {
        M::params(self.params)
    }

    /// The parameters as they arrived, `null` when absent.
    #[must_use]
    pub fn raw(self) -> &'a Value {
        self.params
    }
}

impl<M> Clone for Payload<'_, M> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<M> Copy for Payload<'_, M> {}

impl<M: Method> fmt::Debug for Payload<'_, M> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Payload")
            .field("method", &M::METHOD)
            .field("params", self.params)
            .finish()
    }
}
